/* ProjectAdminDao.insertNotice */
INSERT INTO T_NOTICE (
    NOTICE_TITLE
    , NOTICE_CONTENT
    , NOTICE_TYPE
    , NOTICE_YN
    , FRST_REG_DT
    , FRST_RGTR_ID
    , LAST_MDF_DT
    , LAST_MDFR_ID
) VALUES (
    #{noticeTitle}
    , #{noticeContent}
    , '1'
    , 'Y'
    ,(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
    , #{userId}
    ,(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
    , #{userId}
)

