/* ProjectAdminDao.updateNotice */
update T_NOTICE set
    NOTICE_CONTENT = #{noticeContent}
  , NOTICE_YN = #{noticeYn}
  , LAST_MDF_DT = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
  , LAST_MDFR_ID = #{userId}
where NOTICE_SN = #{noticeSn}::integer

/* ProjectAdminDao.updateUser */
update T_USER set
    LAST_MDF_DT = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')

        , ADMIN_YN = #{adminYn}


        , USER_STATE = #{userState}

where USER_ID = #{userId}

/* ProjectAdminDao.deleteUser */
DELETE FROM T_USER
where USER_ID = #{userId}
